  P[free]=Z;energy=float(np.sum(((P[ii]-P[jj])-np.einsum('nij,nj->ni',rot[ii],edge))**2));rows.append({'iteration':outer+1,'cgSteps':step+1,'linearResidualMaximumM':float(abs(res).max()),'uniformEdgeRigidityEnergyM2':energy})
